import {indianCatalog} from './indian.mjs';
export function personalCatalog(catalog){
 const byId=id=>catalog.find(f=>f.id===id);
 const make=(id,title,grams,emoji)=>({...structuredClone(byId(id)),displayName:title,defaultGrams:grams,emoji});
 const chobani={id:'brand-chobani-20g-vanilla-190',name:'Chobani 20g Protein · Vanilla · 190 g cup',displayName:'Chobani 20g Vanilla',aliases:'chobani yogurt yoghurt yogrut high protein cup',diet:'dairy',category:'Branded yogurt',source:'Product label · Giant Food',sourceUrl:'https://giantfood.com/groceries/product/chobani-20g-protein-lowfat-vanilla-greek-yogurt-cup-6-7-oz-cup/370506',verifiedAt:'2026-10-07',basisGrams:100,defaultGrams:190,portions:[{label:'1 container',grams:190}],image:'assets/chobani-vanilla.jpg',imageCredit:'Chobani product imagery via Giant Food / Syndigo. All brand rights remain with their owners.',note:'Specific vanilla 190 g cup. Check your flavor and package label; other Chobani products differ.',nutrients:Object.fromEntries(Object.entries({kcal:140,protein:20,fat:3,carbs:9,fiber:2}).map(([k,v])=>[k,v/1.9]))};
 const chana={id:'estimate-chana-curry',name:'Chana curry · estimated recipe',displayName:'Chana curry · estimate',aliases:'chickpeas chole curry chana masala',diet:'plant',category:'Your usual foods',source:'Recipe estimate',basisGrams:100,defaultGrams:450,portions:[{label:'Your usual bowl',grams:450}],image:'assets/foods/chana.png',estimated:true,note:'Example portion: 600 kcal, 27 g protein, 85 g carbs; 15–20 g fat and 20–24 g fiber per 450 g. Midpoints are used. Oil, butter and recipe are unverified. Food image is illustrative.',nutrients:Object.fromEntries(Object.entries({kcal:600,protein:27,fat:17.5,carbs:85,fiber:22}).map(([k,v])=>[k,v/4.5]))};
 const latte={id:'estimate-latte',name:'Latte · no sugar · estimated milk portion',displayName:'Your no-sugar latte',aliases:'coffee milk latte',diet:'dairy',source:'Recipe estimate',basisGrams:100,defaultGrams:240,portions:[{label:'Approx. 1 cup milk',grams:240}],estimated:true,emoji:'☕',note:'Estimate assumes approximately one cup of milk. Milk type and amount need confirmation; grams describe the assumed milk portion.',nutrients:Object.fromEntries(Object.entries({kcal:100,protein:8,fat:4,carbs:12,fiber:0}).map(([k,v])=>[k,v/2.4]))};
 const favorites=[chobani,chana,make('168878','Cooked white rice',200,'🍚'),latte,make('169705','Oats · dry weight',50,'🥣'),make('170894','Plain Greek yogurt',170,'🥛'),make('172421','Lentils · cooked, no added oil',180,'🫘'),make('173944','Banana',118,'🍌'),make('172475','Firm tofu',150,'◈'),make('170554','Chia seeds',10,'◈'),make('171267','2% milk',200,'🥛')];
 const indian=indianCatalog(catalog);
 const replacement=new Map(indian.extras.map(f=>[f.id,f]));
 const base=favorites.filter(f=>f.nutrients);
 const shelf=[...base.map(f=>replacement.get(f.id)||f),...indian.favorites.filter(f=>!base.some(x=>x.id===f.id))];
 return {favorites:shelf,extras:[chobani,chana,latte,...indian.extras],combos:[{id:'usual',name:'Your familiar plate',description:'Chana + rice + Chobani + latte',image:'assets/foods/chana.png',estimated:true,items:[[chana.id,450],['168878',200],[chobani.id,190],[latte.id,240]]},{id:'oats',name:'Build your oats bowl',description:'50 g oats + 200 g milk + 10 g chia',emoji:'🥣',items:[['169705',50],['171267',200],['170554',10]]},{id:'snack',name:'Protein + fruit',description:'Chobani Vanilla + a banana',image:'assets/chobani-vanilla.jpg',items:[[chobani.id,190],['173944',118]]}]};
}
export function normalizeSearch(s){return s.toLowerCase().replace(/yogrut|yoghurt/g,'yogurt').replace(/panner/g,'paneer').replace(/\bbhindi\b/g,'okra').replace(/\bpalak\b/g,'spinach').replace(/\baloo\b/g,'potato').replace(/\bgobi\b/g,'cauliflower').replace(/\bdahi\b/g,'curd').replace(/\bchole\b/g,'chana').replace(/\baubergine\b|\bbrinjal\b/g,'eggplant').replace(/\bcapsicum\b/g,'pepper').replace(/\bcoriander leaves\b/g,'cilantro').replace(/[,·]/g,' ').replace(/\s+/g,' ').trim();}
export function matchesFood(food,query){const text=normalizeSearch([food.name,food.displayName,food.aliases].filter(Boolean).join(' '));return normalizeSearch(query).split(' ').every(w=>text.includes(w));}
